package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"reflect"
	"strings"

	"github.com/segmentio/kafka-go"
)

// User represents the internal user model
type User struct {
	ID        string `json:"id"`
	Username  string `json:"username"`
	Email     string `json:"email"`
	Role      string `json:"role"`
	IsAdmin   bool   `json:"is_admin"`
	Quota     int    `json:"quota"`
	Suspended bool   `json:"suspended"`
}

// UserUpdateEvent represents an event from the Kafka topic
type UserUpdateEvent struct {
	UserID  string                 `json:"user_id"`
	Source  string                 `json:"source"`
	Fields  map[string]interface{} `json:"fields"`
}

var userStore = map[string]*User{}

// applyFieldsToUser performs dynamic field assignment from event payload
func applyFieldsToUser(user *User, fields map[string]interface{}) error {
	userVal := reflect.ValueOf(user).Elem()
	userType := userVal.Type()

	for key, value := range fields {
		for i := 0; i < userType.NumField(); i++ {
			field := userType.Field(i)
			jsonTag := strings.Split(field.Tag.Get("json"), ",")[0]
			if jsonTag == key {
				fieldVal := userVal.Field(i)
				if fieldVal.CanSet() {
					switch fieldVal.Kind() {
					case reflect.String:
						if v, ok := value.(string); ok {
							fieldVal.SetString(v)
						}
					case reflect.Bool:
						if v, ok := value.(bool); ok {
							fieldVal.SetBool(v)
						}
					case reflect.Int:
						if v, ok := value.(float64); ok {
							fieldVal.SetInt(int64(v))
						}
					}
				}
				break
			}
		}
	}
	return nil
}

// processMessage handles incoming Kafka messages
func processMessage(msg kafka.Message) error {
	var event UserUpdateEvent
	if err := json.Unmarshal(msg.Value, &event); err != nil {
		return fmt.Errorf("unmarshal error: %w", err)
	}

	user, exists := userStore[event.UserID]
	if !exists {
		user = &User{ID: event.UserID}
		userStore[event.UserID] = user
	}

	// Apply all fields from the event - no field filtering
	return applyFieldsToUser(user, event.Fields)
}

// HTTP endpoint that accepts profile updates and publishes to Kafka
func handleProfileUpdate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var payload struct {
		UserID string                 `json:"user_id"`
		Fields map[string]interface{} `json:"fields"`
	}

	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	event := UserUpdateEvent{
		UserID: payload.UserID,
		Source: "api",
		Fields: payload.Fields,
	}

	msgBytes, _ := json.Marshal(event)

	// Publish to Kafka topic
	writer := &kafka.Writer{
		Addr:  kafka.TCP("kafka:9092"),
		Topic: "user-updates",
	}
	defer writer.Close()

	err := writer.WriteMessages(context.Background(), kafka.Message{
		Key:   []byte(payload.UserID),
		Value: msgBytes,
	})
	if err != nil {
		http.Error(w, "publish failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusAccepted)
	json.NewEncoder(w).Encode(map[string]string{"status": "queued"})
}

func startConsumer() {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers: []string{"kafka:9092"},
		Topic:   "user-updates",
		GroupID: "user-processor",
	})
	defer reader.Close()

	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			log.Printf("read error: %v", err)
			continue
		}
		if err := processMessage(msg); err != nil {
			log.Printf("process error: %v", err)
		}
	}
}

func main() {
	// Seed a test user
	userStore["user-123"] = &User{
		ID: "user-123", Username: "alice", Email: "alice@example.com",
		Role: "viewer", IsAdmin: false, Quota: 100, Suspended: false,
	}

	go startConsumer()

	http.HandleFunc("/api/v1/profile/update", handleProfileUpdate)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
